// Minimización de datos: la IA nunca recibe nombre ni email del cliente
// y el mensaje se limpia de identificadores antes de guardarse o procesarse.
const cfg = $('Config').first().json;
const limpiar = (t) => String(t ?? '').replace(/\s+/g, ' ').trim();
const reglas = [
  ['CBU/CVU', /\b\d{22}\b/g, '[CBU/CVU REDACTADO]'],
  ['Email', /[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g, '[EMAIL REDACTADO]'],
  ['Tarjeta', /\b(?:\d{4}[ -]?){3}\d{4}\b/g, '[TARJETA REDACTADA]'],
  ['DNI', /\b(?:DNI|D\.N\.I\.?|documento)[\s:nNº°ro.]*\d{1,2}\.?\d{3}\.?\d{3}\b/gi, '[DNI REDACTADO]'],
  ['DNI', /(?<![\d.$])(?<!ARS ?)(?<!USD ?)\b\d{2}\.\d{3}\.\d{3}\b/g, '[DNI REDACTADO]'],
  ['Telefono', /\b(?:tel(?:[eé]fono)?|cel(?:ular)?|whats ?app|wsp)[\s:.]*\+?[\d\s()-]{8,16}\d/gi, '[TELEFONO REDACTADO]'],
  ['Telefono', /(?:\+?54[\s-]?)?(?:9[\s-]?)?(?:\(?0?\d{2,4}\)?[\s-]?)?(?:15[\s-]?)?\d{4}[\s-]\d{4}\b/g, '[TELEFONO REDACTADO]'],
];
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let mensaje = limpiar(j.mensaje);
  const redactados = new Set();
  for (const [tipo, re, marca] of reglas) {
    if (re.test(mensaje)) { redactados.add(tipo); }
    re.lastIndex = 0;
    mensaje = mensaje.replace(re, marca);
  }
  mensaje = mensaje.slice(0, cfg.max_caracteres_mensaje);
  const email = limpiar(j.email).toLowerCase();
  out.push({ json: {
    nombre: limpiar(j.nombre).slice(0, 80),
    email,
    email_valido: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email),
    tipo_contacto: ['Interesado', 'Inquilino', 'Propietario', 'Otro'].includes(j.tipo_contacto) ? j.tipo_contacto : 'Otro',
    mensaje_minimizado: mensaje,
    largo_mensaje: mensaje.length,
    datos_redactados: [...redactados],
    es_remitente_interno: email === String(cfg.email_remitente_domus).toLowerCase(),
    recibida: new Date().toISOString(),
    execution_id: String($execution.id),
  }});
}
return out;

// Unifica las dos ramas: contacto existente (resultado de la búsqueda) o contacto recién creado.
const j = $input.first().json;
const existente = Array.isArray(j.results);
return [{ json: { contacto_id: existente ? j.results[0].id : j.id, contacto_nuevo: !existente } }];

// Prompt dinámico: combina el prompt versionado del nodo Config con variables de la ejecución.
// La IA recibe solo el mensaje minimizado y el tipo de remitente (nunca nombre ni email).
const cfg = $('Config').first().json;
const d = $('Datos · Minimizar y normalizar').first().json;
const historial = $('Notion · Historial del contacto (memoria)').first().json.results || [];
const texto = [
  `Tipo de remitente declarado: ${d.tipo_contacto}`,
  `Consultas previas del mismo contacto: ${historial.length}`,
  'Mensaje (datos personales ya redactados), delimitado por <<< y >>>:',
  '<<<', d.mensaje_minimizado, '>>>',
].join('\n');
const body = {
  systemInstruction: { parts: [{ text: cfg.prompt_clasificador }] },
  contents: [{ role: 'user', parts: [{ text: texto }] }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: cfg.max_tokens_clasificador,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        categoria: { type: 'STRING', enum: ['Comercial', 'Mantenimiento', 'Administrativa', 'Otro'] },
        urgencia: { type: 'STRING', enum: ['Alta', 'Media', 'Baja'] },
        resumen: { type: 'STRING' },
        intencion: { type: 'STRING' },
        confianza: { type: 'NUMBER' },
      },
      required: ['categoria', 'urgencia', 'resumen', 'intencion', 'confianza'],
      propertyOrdering: ['categoria', 'urgencia', 'resumen', 'intencion', 'confianza'],
    },
  },
};
return [{ json: { body } }];

// Valida la salida del modelo antes de usarla (guardrail). Si algo no cumple, se lanza un error
// que viaja por la salida de error hacia el registro en Notion + alerta en Slack.
const cfg = $('Config').first().json;
const r = $input.first().json;
const cand = r.candidates?.[0];
const texto = (cand?.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join('').trim();
if (!texto) throw new Error(`La IA no devolvió contenido (finishReason: ${cand?.finishReason || 'desconocido'})`);
let c;
try { c = JSON.parse(texto); } catch (e) { throw new Error('La respuesta de la IA no es JSON válido: ' + texto.slice(0, 200)); }
if (!['Comercial', 'Mantenimiento', 'Administrativa', 'Otro'].includes(c.categoria)) throw new Error('Categoría fuera de dominio: ' + c.categoria);
if (!['Alta', 'Media', 'Baja'].includes(c.urgencia)) throw new Error('Urgencia fuera de dominio: ' + c.urgencia);
return [{ json: {
  categoria: c.categoria,
  urgencia: c.urgencia,
  resumen: String(c.resumen || '').slice(0, 500),
  intencion: String(c.intencion || '').slice(0, 120),
  confianza: Number(c.confianza) || 0,
  tokens_clasificacion: Number(r.usageMetadata?.totalTokenCount) || 0,
  modelo_clasificador: r.modelVersion || cfg.modelo_clasificador,
} }];

// RAG: arma el contexto con artículos VERIFICADOS de la Base de Conocimiento de la categoría,
// suma la memoria del contacto (últimas consultas) y construye el prompt dinámico del redactor.
const cfg = $('Config').first().json;
const d = $('Datos · Minimizar y normalizar').first().json;
const c = $('IA · Validar clasificación').first().json;
const plano = (rt) => (rt || []).map(t => t.plain_text || '').join('');
const kb = $input.first().json.results || [];
const articulos = kb.map((p, i) => ({
  id: p.id,
  ref: `A${i + 1}`,
  tema: plano(p.properties?.Tema?.title),
  contenido: plano(p.properties?.Contenido?.rich_text),
}));
const historial = ($('Notion · Historial del contacto (memoria)').first().json.results || []).map(p =>
  `- ${(p.properties?.Recibida?.date?.start || '').slice(0, 10)}: ${plano(p.properties?.['Resumen IA']?.rich_text) || '(sin resumen)'} [${p.properties?.Estado?.select?.name || 's/estado'}]`);
const contexto = articulos.length
  ? articulos.map(a => `[${a.ref}] ${a.tema}: ${a.contenido}`).join('\n')
  : 'NO HAY ARTÍCULOS VERIFICADOS PARA ESTA CATEGORÍA.';
const texto = [
  `CATEGORÍA: ${c.categoria} | URGENCIA: ${c.urgencia}`,
  `INTENCIÓN DETECTADA: ${c.intencion}`,
  '', 'HISTORIAL DEL CONTACTO (memoria):', historial.join('\n') || '- Es su primera consulta.',
  '', 'BASE DE CONOCIMIENTO VERIFICADA:', contexto,
  '', 'MENSAJE DEL CLIENTE (datos personales redactados), delimitado por <<< y >>>:', '<<<', d.mensaje_minimizado, '>>>',
].join('\n');
const body = {
  systemInstruction: { parts: [{ text: cfg.prompt_redactor }] },
  contents: [{ role: 'user', parts: [{ text: texto }] }],
  generationConfig: {
    temperature: 0.3,
    maxOutputTokens: cfg.max_tokens_redactor,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        asunto: { type: 'STRING' },
        cuerpo: { type: 'STRING' },
        referencias: { type: 'ARRAY', items: { type: 'STRING' } },
        confianza: { type: 'STRING', enum: ['Alta', 'Media', 'Baja'] },
        requiere_atencion_especial: { type: 'BOOLEAN' },
      },
      required: ['asunto', 'cuerpo', 'referencias', 'confianza', 'requiere_atencion_especial'],
      propertyOrdering: ['asunto', 'cuerpo', 'referencias', 'confianza', 'requiere_atencion_especial'],
    },
  },
};
return [{ json: { body, articulos, contexto } }];

// Guardrail anti-alucinación: valida el JSON, verifica que los números (precios, plazos, porcentajes)
// del borrador existan en la Base de Conocimiento usada y marca alertas para el revisor humano.
const cfg = $('Config').first().json;
const prep = $('IA · Preparar prompt de respuesta (RAG)').first().json;
const cla = $('IA · Validar clasificación').first().json;
const r = $input.first().json;
const cand = r.candidates?.[0];
const texto = (cand?.content?.parts || []).filter(p => !p.thought).map(p => p.text || '').join('').trim();
if (!texto) throw new Error(`La IA no devolvió contenido (finishReason: ${cand?.finishReason || 'desconocido'})`);
let o;
try { o = JSON.parse(texto); } catch (e) { throw new Error('El borrador de la IA no es JSON válido: ' + texto.slice(0, 200)); }
const cuerpo = String(o.cuerpo || '').trim();
if (cuerpo.length < 40) throw new Error('El borrador es demasiado corto para enviarse (' + cuerpo.length + ' caracteres)');
const RE_NUM = /\d[\d.,]*\d|\d/g;
const norm = (s) => s.replace(/[.,\s]/g, '');
const numerosBase = new Set((String(prep.contexto || '').match(RE_NUM) || []).map(norm));
const numeros = cuerpo.match(RE_NUM) || [];
const sinRespaldo = [...new Set(numeros.filter(n => norm(n).length >= 2 && !numerosBase.has(norm(n))))];
const refs = Array.isArray(o.referencias) ? o.referencias : [];
const usados = prep.articulos.filter(a => refs.includes(a.ref));
const alertas = [];
if (!prep.articulos.length) alertas.push('No había artículos verificados para esta categoría.');
if (!usados.length) alertas.push('El borrador no cita ningún artículo de la base.');
if (sinRespaldo.length) alertas.push('Números sin respaldo en la base: ' + sinRespaldo.join(', '));
if (o.requiere_atencion_especial) alertas.push('La IA sugiere atención especial (cliente molesto, tema legal o fuera de la base).');
return [{ json: {
  asunto: String(o.asunto || 'Tu consulta a Domus Propiedades').slice(0, 120),
  cuerpo: cuerpo.slice(0, 1900),
  confianza: ['Alta', 'Media', 'Baja'].includes(o.confianza) ? o.confianza : 'Baja',
  articulos_ids: usados.map(a => a.id),
  articulos_txt: usados.map(a => `${a.ref} ${a.tema}`).join(' · ') || 'ninguno',
  alertas,
  semaforo: alertas.length === 0 ? '🟢' : (sinRespaldo.length || !prep.articulos.length ? '🔴' : '🟡'),
  tokens_total: cla.tokens_clasificacion + (Number(r.usageMetadata?.totalTokenCount) || 0),
  modelos: `${cla.modelo_clasificador} + ${r.modelVersion || cfg.modelo_redactor}`,
} }];

