// Centraliza los errores de IA y de envío: identifica el nodo, normaliza el mensaje
// y arma el registro para la base "Log de Ejecuciones" de Notion.
const cfg = $('Config').first().json;
const j = $input.first().json;
const raw = j.error;
const detalle = String(typeof raw === 'string' ? raw : (raw?.message || raw?.description || JSON.stringify(raw ?? j))).slice(0, 1800);
let nodo = 'desconocido';
try { nodo = $prevNode.name; } catch (e) {}
let consulta_id = null;
try { consulta_id = $('Notion · Crear consulta (Pendiente)').first().json.id; } catch (e) {}
const tipo = nodo.startsWith('IA') ? 'Error IA' : (nodo.startsWith('Email') ? 'Error envio' : 'Error API');
const properties = {
  'Evento': { title: [{ text: { content: `${tipo} en "${nodo}"` } }] },
  'Tipo': { select: { name: tipo } },
  'Workflow': { select: { name: 'WF01 Atencion' } },
  'Nodo': { rich_text: [{ text: { content: nodo } }] },
  'Detalle': { rich_text: [{ text: { content: detalle } }] },
  'ID ejecucion': { rich_text: [{ text: { content: String($execution.id) } }] },
  'Fecha': { date: { start: new Date().toISOString() } },
};
if (consulta_id) properties['Consulta'] = { relation: [{ id: consulta_id }] };
return [{ json: {
  tipo, nodo, detalle, consulta_id: consulta_id || '',
  body_log: { parent: { database_id: cfg.notion_db_log }, properties },
} }];
